                // Apply tanh
                val = tanhf(val);
                // Apply scaling
                val = val * scaling_factor;
                // Apply bias
                val = val + bias_val;

                if (val > max_val) {
                    max_val = val;
                }
            }
        }
    }

    output[idx] = max_val;
