    hipLaunchKernelGGL(fused_dropout_softmax_kernel, 
        dim3(rows), dim3(block_size), shared_mem_size, 0,
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        rows,
        cols,
        dropout_p,
        scale,
        seed,
        training
    );

