    } else {
        int num_blocks = (total + block_size - 1) / block_size;

        fused_bn_scale_opt_kernel<<<num_blocks, block_size, shared_mem_size>>>(
            input.data_ptr<float>(),
            output.data_ptr<float>(),
            weights.data_ptr<float>(),
            biases.data_ptr<float>(),
            N, C, HW
        );
