    int blocks = N * C;

    fused_instance_norm_div_kernel_v2<<<blocks, threads>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        N, C, H, W,
        divide_by,
        eps
    );

    return output;
}
