        local_sum += fmaxf(v1.x, v1.y) + fmaxf(v1.z, v1.w);
        local_sum += fmaxf(v2.x, v2.y) + fmaxf(v2.z, v2.w);
        local_sum += fmaxf(v3.x, v3.y) + fmaxf(v3.z, v3.w);
    }

    // Handle remaining elements
