# Optimized fused kernel with vectorized memory access
fused_scale_maxpool_clamp_source = """
#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <float.h>

#define BLOCK_X 32
#define BLOCK_Y 8

template<int POOL_SIZE>
__global__ void fused_scale_maxpool_clamp_kernel_v4(
    const float* __restrict__ input,
    const float* __restrict__ scale,
    float* __restrict__ output,
    const int batch_size,
    const int channels,
    const int in_height,
    const int in_width,
    const int out_height,
    const int out_width,
    const float clamp_min,
    const float clamp_max
) {
    int ow = blockIdx.x * BLOCK_X + threadIdx.x;
    int oh = blockIdx.y * BLOCK_Y + threadIdx.y;
    int bc = blockIdx.z;

    if (ow >= out_width || oh >= out_height) return;

    int c = bc % channels;
    int b = bc / channels;

    // Load scale value (will be cached in L1/L2)
    float s = scale[c];

    // Compute max over pooling window
    float max_val = -FLT_MAX;

    int h_start = oh * POOL_SIZE;
    int w_start = ow * POOL_SIZE;

    // Base index for this batch and channel
    int base_idx = (b * channels + c) * in_height * in_width;

    // Unrolled pooling loop
    #pragma unroll
    for (int dh = 0; dh < POOL_SIZE; dh++) {
        int row_idx = base_idx + (h_start + dh) * in_width + w_start;
        #pragma unroll
        for (int dw = 0; dw < POOL_SIZE; dw++) {
            float val = __ldg(&input[row_idx + dw]) * s;
            max_val = fmaxf(max_val, val);
        }
    }

    // Clamp using native fmin/fmax
    max_val = fminf(fmaxf(max_val, clamp_min), clamp_max);

    int out_idx = ((b * channels + c) * out_height + oh) * out_width + ow;
    output[out_idx] = max_val;
}

torch::Tensor fused_scale_maxpool_clamp_hip(
    torch::Tensor input,
    torch::Tensor scale,
    int pool_size,
    float clamp_min,
    float clamp_max
) {
    const int batch_size = input.size(0);
    const int channels = input.size(1);
    const int in_height = input.size(2);
    const int in_width = input.size(3);

    const int out_height = in_height / pool_size;
    const int out_width = in_width / pool_size;

    auto output = torch::empty({batch_size, channels, out_height, out_width}, input.options());

    dim3 block(BLOCK_X, BLOCK_Y);
    dim3 grid(
        (out_width + BLOCK_X - 1) / BLOCK_X,
        (out_height + BLOCK_Y - 1) / BLOCK_Y,
        batch_size * channels
    );

    // Use template specialization for pool_size = 4
    fused_scale_maxpool_clamp_kernel_v4<4><<<grid, block, 0, at::cuda::getCurrentCUDAStream()>>>(
        input.data_ptr<float>(),
        scale.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        channels,
        in_height,
        in_width,
        out_height,
        out_width,
        clamp_min,
        clamp_max
    );

    return output;
}
