        # Fused Scale + MaxPool + Clamp
        x = self.fused_module.fused_scale_maxpool_clamp_hip(
            x.contiguous(),
            self.scale.view(-1).contiguous(),
            self.maxpool_kernel_size,
            self.clamp_min,
            self.clamp_max
        )
        return x


