#include <hip/hip_runtime.h>
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <float.h>

#define BLOCK_X 32
#define BLOCK_Y 8

// Each thread handles one output pixel, uses float4 for 4x faster reads
__global__ void fused_scale_maxpool_clamp_kernel_vec4(
    const float* __restrict__ input,
    const float* __restrict__ scale,
    float* __restrict__ output,
    const int batch_size,
    const int channels,
    const int in_height,
    const int in_width,
    const int out_height,
    const int out_width,
    const float clamp_min,
    const float clamp_max
) {
    int ow = blockIdx.x * BLOCK_X + threadIdx.x;
    int oh = blockIdx.y * BLOCK_Y + threadIdx.y;
    int bc = blockIdx.z;

    if (ow >= out_width || oh >= out_height) return;

    int c = bc % channels;
    int b = bc / channels;

    // Load scale value
    float s = scale[c];

    // Compute max over pooling window (4x4)
    float max_val = -FLT_MAX;

    int h_start = oh * 4;  // pool_size = 4
    int w_start = ow * 4;

    // Base pointer for this batch and channel
    const float* base_ptr = input + (b * channels + c) * in_height * in_width;

    // Process 4 rows, each row uses float4 load (4 elements)
    #pragma unroll
    for (int dh = 0; dh < 4; dh++) {
        int row_start = (h_start + dh) * in_width + w_start;
        // Load 4 consecutive floats as float4
        float4 vals = *reinterpret_cast<const float4*>(&base_ptr[row_start]);

        // Apply scale and find max
        max_val = fmaxf(max_val, vals.x * s);
        max_val = fmaxf(max_val, vals.y * s);
        max_val = fmaxf(max_val, vals.z * s);
        max_val = fmaxf(max_val, vals.w * s);
    }

    // Clamp
    max_val = fminf(fmaxf(max_val, clamp_min), clamp_max);

    int out_idx = ((b * channels + c) * out_height + oh) * out_width + ow;
    output[out_idx] = max_val;
}

